1	/**
2	 * What MHPCO knows about the customer's standing: the facts of their history
3	 * with the office that its policy-wide discount rules are written against.
4	 */
5	export interface Customer {
6	  yearsWithMHPCO: number;
7	  /** Contracts this customer already holds, before the one being quoted. */
8	  previousContracts?: number;
9	}
10	
11	export interface Item {
12	  type: string;
13	  material?: string;
14	  cursed?: boolean;
15	  enchantment?: number;
16	}
17	
18	/**
19	 * How MHPCO prices one insurable type. `kind` is the pricing category the
20	 * office files the type under: main items are priced one by one, components
21	 * are priced as a group so that the building-block offer can be applied.
22	 */
23	interface PriceListEntry {
24	  kind: "main" | "component";
25	  basePremium: number;
26	  insuranceValue: number;
27	}
28	
29	/**
30	 * The MHPCO price list: the office's record of every type it insures at all.
31	 * Absence from this list is the office's rejection condition — MHPCO insures
32	 * exactly what it has priced.
33	 */
34	const PRICE_LIST: Record<string, PriceListEntry> = {
35	  sword: { kind: "main", basePremium: 100, insuranceValue: 1000 },
36	  amulet: { kind: "main", basePremium: 60, insuranceValue: 600 },
37	  staff: { kind: "main", basePremium: 80, insuranceValue: 800 },
38	  potion: { kind: "main", basePremium: 40, insuranceValue: 400 },
39	  rune: { kind: "component", basePremium: 25, insuranceValue: 250 },
40	  moonstone: { kind: "component", basePremium: 25, insuranceValue: 250 },
41	};
42	const BLOCK_SIZE = 3;
43	const BLOCK_BASE_PREMIUM = 60;
44	const CURSE_SURCHARGE_RATE = 0.5;
45	const HIGH_ENCHANTMENT_LEVEL = 5;
46	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
47	const LOYALTY_YEARS = 2;
48	const LOYALTY_DISCOUNT_RATE = 0.2;
49	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
50	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
51	const PROCESSING_FEE = 5;
52	const DEDUCTIBLE_PER_DAMAGE = 100;
53	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
54	
55	/** MHPCO insures exactly the types on its price list; anything else it turns away. */
56	function priceListEntry(item: Item): PriceListEntry {
57	  const entry = PRICE_LIST[item.type];
58	  if (entry === undefined) {
59	    throw new Error(`MHPCO does not insure items of type "${item.type}"`);
60	  }
61	  return entry;
62	}
63	
64	function isComponent(item: Item): boolean {
65	  return priceListEntry(item).kind === "component";
66	}
67	
68	function isMainItem(item: Item): boolean {
69	  return priceListEntry(item).kind === "main";
70	}
71	
72	/** What the customer pays to insure the item, before any offer or modifier. */
73	function itemBasePremium(item: Item): number {
74	  return priceListEntry(item).basePremium;
75	}
76	
77	/**
78	 * What MHPCO insures the item for. A price-list fact: pricing offers such as
79	 * the building block and premium modifiers such as a curse surcharge move what
80	 * the customer pays, never what the office insures the item for.
81	 */
82	function itemInsuranceValue(item: Item): number {
83	  return priceListEntry(item).insuranceValue;
84	}
85	
86	/**
87	 * The building-block offer: MHPCO's standing promotion on a group of alike
88	 * components. It is a pricing offer, not a price-list fact, so it lives beside
89	 * the price list rather than inside it.
90	 */
91	function alikeGroupBasePremium(group: Item[]): number {
92	  return group.length === BLOCK_SIZE
93	    ? BLOCK_BASE_PREMIUM
94	    : group.reduce((total, component) => total + itemBasePremium(component), 0);
95	}
96	
97	/** Components are "alike" when they are of exactly the same type. */
98	function alikeKey(component: Item): string {
99	  return component.type;
100	}
101	
102	function componentsBasePremium(components: Item[]): number {
103	  const alikeGroups = new Map<string, Item[]>();
104	  for (const component of components) {
105	    const key = alikeKey(component);
106	    alikeGroups.set(key, [...(alikeGroups.get(key) ?? []), component]);
107	  }
108	  return [...alikeGroups.values()].reduce(
109	    (total, group) => total + alikeGroupBasePremium(group),
110	    0,
111	  );
112	}
113	
114	function curseSurcharge(item: Item): number {
115	  return item.cursed === true
116	    ? itemBasePremium(item) * CURSE_SURCHARGE_RATE
117	    : 0;
118	}
119	
120	function isHighlyEnchanted(item: Item): boolean {
121	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
122	}
123	
124	function highEnchantmentSurcharge(item: Item): number {
125	  return isHighlyEnchanted(item)
126	    ? itemBasePremium(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
127	    : 0;
128	}
129	
130	/**
131	 * Item-specific modifiers apply to the base premium of the affected item and
132	 * are added to it, never multiplied onto it. Each risk rule is independent:
133	 * its own condition, its own rate.
134	 */
135	function itemSpecificModifiers(item: Item): number {
136	  return curseSurcharge(item) + highEnchantmentSurcharge(item);
137	}
138	
139	function mainItemsBasePremium(mainItems: Item[]): number {
140	  return mainItems.reduce((total, item) => total + itemBasePremium(item), 0);
141	}
142	
143	/** The policy base premium: the sum of all unmodified item base premiums. */
144	function policyBasePremiumFor(items: Item[]): number {
145	  return (
146	    mainItemsBasePremium(items.filter(isMainItem)) +
147	    componentsBasePremium(items.filter(isComponent))
148	  );
149	}
150	
151	/** The item-specific surcharges of every affected item, summed. */
152	function itemSpecificModifiersFor(items: Item[]): number {
153	  return items
154	    .filter(isMainItem)
155	    .reduce((total, item) => total + itemSpecificModifiers(item), 0);
156	}
157	
158	/**
159	 * Rounding in the MHPCO's favour is a single policy with two arms: an amount
160	 * the customer pays goes up, an amount MHPCO pays out goes down. This is the
161	 * premium arm; it is named for the amount it rounds so that a payout can never
162	 * reach it by mistake.
163	 */
164	function roundPremiumInMHPCOsFavour(premium: number): number {
165	  return Math.ceil(premium);
166	}
167	
168	/** Every item in a quote is treated as a first insurance. */
169	function firstInsuranceSurcharge(policyBasePremium: number): number {
170	  return policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
171	}
172	
173	function isLongStanding(customer: Customer): boolean {
174	  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
175	}
176	
177	function loyaltyDiscount(customer: Customer, policyBasePremium: number): number {
178	  return isLongStanding(customer)
179	    ? policyBasePremium * LOYALTY_DISCOUNT_RATE
180	    : 0;
181	}
182	
183	function isFollowUpContract(customer: Customer): boolean {
184	  return (customer.previousContracts ?? 0) > 0;
185	}
186	
187	function followUpDiscount(
188	  customer: Customer,
189	  policyBasePremium: number,
190	): number {
191	  return isFollowUpContract(customer)
192	    ? policyBasePremium * FOLLOW_UP_DISCOUNT_RATE
193	    : 0;
194	}
195	
196	/**
197	 * Policy-wide modifiers apply to the policy base premium (the sum of all item
198	 * base premiums) and are added to it, never multiplied onto it. Each rule is
199	 * independent: its own condition, its own rate. Surcharges raise the premium
200	 * and discounts lower it; each is computed as a positive amount off the
201	 * unmodified policy base premium and given its sign here.
202	 */
203	function policyWideModifiers(
204	  customer: Customer,
205	  policyBasePremium: number,
206	): number {
207	  return (
208	    firstInsuranceSurcharge(policyBasePremium) -
209	    loyaltyDiscount(customer, policyBasePremium) -
210	    followUpDiscount(customer, policyBasePremium)
211	  );
212	}
213	
214	export function quote(customer: Customer, items: Item[]): number {
215	  const policyBasePremium = policyBasePremiumFor(items);
216	  const premium =
217	    policyBasePremium +
218	    itemSpecificModifiersFor(items) +
219	    policyWideModifiers(customer, policyBasePremium) +
220	    PROCESSING_FEE;
221	  return roundPremiumInMHPCOsFavour(premium);
222	}
223	
224	export interface Damage {
225	  itemType: string;
226	  amount: number;
227	}
228	
229	export interface Incident {
230	  cause: string;
231	  damages: Damage[];
232	}
233	
234	export interface ClaimResult {
235	  payout: number;
236	  remainingCap: number;
237	}
238	
239	/** A policy MHPCO has written: the items it covers and the cap still available. */
240	export interface Policy {
241	  items: Item[];
242	  remainingCap: number;
243	}
244	
245	/** The insurance sum: what MHPCO insures the policy's items for, unmodified. */
246	function insuranceSumFor(items: Item[]): number {
247	  return items.reduce((total, item) => total + itemInsuranceValue(item), 0);
248	}
249	
250	/**
251	 * The cap MHPCO writes a policy for: twice the insurance sum. It is derived
252	 * from the unmodified insurance values alone — premium modifiers such as a
253	 * curse surcharge raise what the customer pays, never what the office owes.
254	 */
255	function capFor(items: Item[]): number {
256	  return insuranceSumFor(items) * CAP_MULTIPLE_OF_INSURANCE_SUM;
257	}
258	
259	export function createPolicy(items: Item[]): Policy {
260	  return { items, remainingCap: capFor(items) };
261	}
262	
263	/** Rounded in MHPCO's favour: a payout of 350.5 G is settled at 350 G. */
264	function roundPayoutInMHPCOsFavour(payout: number): number {
265	  return Math.floor(payout);
266	}
267	
268	/** What one damage earns before the policy's cap is consulted. */
269	function reimbursementFor(damage: Damage): number {
270	  return damage.amount - DEDUCTIBLE_PER_DAMAGE;
271	}
272	
273	/** What the incident earns on its own merits, cap not yet applied. */
274	function reimbursementForIncident(incident: Incident): number {
275	  return incident.damages.reduce(
276	    (total, damage) => total + reimbursementFor(damage),
277	    0,
278	  );
279	}
280	
281	/**
282	 * The settlement: what MHPCO actually pays. The office never pays more than
283	 * the cap still available on the policy, however much the damage earns.
284	 */
285	function settlementFor(policy: Policy, incident: Incident): number {
286	  return roundPayoutInMHPCOsFavour(
287	    Math.min(reimbursementForIncident(incident), policy.remainingCap),
288	  );
289	}
290	
291	/** Settling a claim pays the settlement and draws it down from the policy's cap. */
292	export function claim(policy: Policy, incident: Incident): ClaimResult {
293	  const payout = settlementFor(policy, incident);
294	  policy.remainingCap -= payout;
295	  return { payout, remainingCap: policy.remainingCap };
296	}
