118	    const customer = { yearsWithMHPCO: 0, previousContracts: 0 };
119	    const items = [
120	      { type: "sword", material: "steel", enchantment: 3, cursed: true },
121	    ];
122	    expect(quote(customer, items)).toBe(165);
123	  });
124	  it("quotes a long-standing customer's second contract: cursed sword enchantment 7, 3 years -- premium 160 G", () => {
125	    const customer = { yearsWithMHPCO: 3, previousContracts: 1 };
126	    const items = [
127	      { type: "sword", material: "steel", enchantment: 7, cursed: true },
128	    ];
129	    expect(quote(customer, items)).toBe(160);
130	  });
